/* ---------- helpers ---------- */
const TODAY = new Date(2026, 8, 2); // 2 Eylül 2026 (demo tarihi)
const DAY = 86400000;
const addDays = (d, n) => new Date(new Date(d).getTime() + n * DAY);
const iso = d => { const x = new Date(d); return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`; };
const MONTHS = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
const MON3 = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
const fdate = d => { if (!d) return "—"; const x = new Date(d); return `${x.getDate()} ${MON3[x.getMonth()]} ${x.getFullYear()}`; };
const fdateS = d => { if (!d) return "—"; const x = new Date(d); return `${x.getDate()} ${MON3[x.getMonth()]}`; };
const daysBetween = (a, b) => Math.round((new Date(b) - new Date(a)) / DAY);
const daysFromToday = d => daysBetween(TODAY, d);
const money = (v, cur = "TL", dec) => {
  if (v == null || isNaN(v)) return "—";
  const n = Number(v);
  const d = dec != null ? dec : (Math.abs(n) >= 1000 ? 0 : 2);
  const s = n.toLocaleString("tr-TR", { minimumFractionDigits: d, maximumFractionDigits: d });
  return cur === "TL" ? `${s} ₺` : cur === "USD" ? `$${s}` : cur === "EUR" ? `€${s}` : `${s} ${cur}`;
};
const num = (v, d = 0) => Number(v || 0).toLocaleString("tr-TR", { minimumFractionDigits: d, maximumFractionDigits: d });
const pct = v => `%${num(v, v % 1 ? 1 : 0)}`;
const sum = (arr, f) => arr.reduce((a, x) => a + (f ? f(x) : x), 0);
const by = (arr, f) => { const m = {}; arr.forEach(x => { const k = f(x); (m[k] = m[k] || []).push(x); }); return m; };
const uniq = arr => [...new Set(arr)];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const initials = n => n.split(" ").map(p => p[0]).join("").slice(0, 2).toUpperCase();
const slug = s => (s || "").toLowerCase().replace(/ı/g, "i").replace(/ğ/g, "g").replace(/ü/g, "u").replace(/ş/g, "s").replace(/ö/g, "o").replace(/ç/g, "c");
const norm = s => slug(s).replace(/[^a-z0-9]/g, "");
let _id = 1000;
const nid = p => `${p}${++_id}`;
/* deterministic pseudo-random for seed data */
function rng(seed) { let s = seed >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
