const CATS = CAT_C.map(([id, name, pages]) => ({ id, name, pages }));
const GROUPS = CAT_G.map(([id, name, en, cat, page, cols, thread, angle, src, cur, img], i) => ({ id, i, name, en, cat, page, cols, thread, angle, src, cur, img }));
const GIDX = {}; GROUPS.forEach(g => GIDX[g.id] = g);
const PRODUCTS = CAT_P.map(([code, gi, vals, price, box]) => {
  const g = GROUPS[gi];
  return { code, gi, g, name: g.name, spec: vals, list: price, cur: g.cur, box: box || 0, thread: g.thread, angle: g.angle, src: g.src, cat: g.cat, page: g.page };
});
const PIDX = {}; PRODUCTS.forEach((p, i) => PIDX[p.code] = i);
const prod = code => PRODUCTS[PIDX[code]];
const catName = id => (CATS.find(c => c.id === id) || {}).name || "";
/* spec helpers */
const specPairs = p => p.g.cols.map((c, i) => [c, p.spec[i]]).filter(x => x[1]);
const specText = p => specPairs(p).map(x => x[1]).join(" · ");
const hoseDia = p => { const i = p.g.cols.findIndex(c => /HORTUM/.test(c)); return i >= 0 ? p.spec[i] : ""; };
const threadSize = p => { const i = p.g.cols.findIndex(c => /DİŞ|ÖLÇÜ|ANMA/.test(c) && !/HORTUM/.test(c)); return i >= 0 ? p.spec[i] : (p.spec.find(x => /\d/.test(x)) || ""); };
const PACK = p => p.box ? `${p.box} adet / kutu` : "Adet olarak";
const TECH = p => {
  const t = p.thread, a = p.angle, s = p.src;
  const base = /Hortum/i.test(p.name) ? "Sentetik kauçuk, çelik örgülü; SAE 100 standardı" : /Pnömatik/i.test(p.name) ? "POM gövde, nikel kaplı pirinç bağlantı; 0-10 bar" : /Sarı|Prinç/i.test(p.name) ? "CW617N pirinç; 40 bar" : /Kelepçe/i.test(p.name) ? "Polyamid / çelik, DIN 3015" : "Karbon çelik (C45), trivalent çinko kaplama";
  const pr = /Flanş/i.test(p.name) ? (/6000/.test(p.name) ? "420 bar (6000 psi)" : "210 bar (3000 psi)") : /ORFS/.test(t) ? "400 bar" : /BSP|UNF|Metrik/.test(t) ? "350 bar" : "";
  return [base, t ? `Diş: ${t}` : "", a ? `Açı: ${a}` : "", pr ? `Çalışma basıncı: ${pr}` : "", s === "uretim" ? "Özteknik üretimi" : "Distribütörlük ürünü"].filter(Boolean).join(" · ");
};
