  const dias = ['1/4"', '3/8"', '1/2"', '5/8"', '3/4"', '1"', '1"1/4', '1"1/2', '2"'];
  const press = { "R1 AT/SC": [225, 180, 160, 130, 105, 88, 63, 50, 40], "R2 AT/SC": [400, 330, 275, 250, 215, 165, 125, 90, 80], "R9 4SH-4SP": [0, 0, 0, 445, 420, 380, 350, 290, 250] };
  const pr = press[type][dias.indexOf(dia)] || 0;
