  const applyPaste = () => { let n = 0; paste.split(/\n/).forEach(line => { const m = line.match(/(ÖT\/?\s?\d{3,4}-\d{2}(-\d)?)[\s;,\t]+(\d+)/i) || line.match(/(\d{3,4}-\d{2})[\s;,\t]+(\d+)/); if (m) { const code = m[1].toUpperCase().replace(/^ÖT\/?\s?/, "ÖT/").replace(/^(\d)/, "ÖT/$1"); if (prod(code)) { S.addToCart(code, +m[m.length - 1]); n++; } } }); S.toast(n ? `${n} satır sepete eklendi` : "Tanınan satır yok — 'ÖT/110-01 100' biçiminde yazın", n ? "ok" : "err"); setPaste(""); setTool("sepet"); };
