        {cart.length ? <Card pad={false}><div style={{ padding: "0 12px" }}>{cart.map(l => { const p = prod(l.code); const pr = priceFor(db, cust, l.code, l.qty); return <div key={l.code} className="row" style={{ padding: "10px 0", borderBottom: "1px solid var(--line)" }}><div style={{ width: 48, height: 40, borderRadius: 8, background: "#F7F8FA", display: "grid", placeItems: "center", overflow: "hidden", flex: "none" }} onClick={() => S.openProduct(l.code)}><PImg p={p} h={40} /></div><div className="grow" style={{ minWidth: 0 }}><div className="b">{l.code}</div><div className="xs mut ell">{p.name}</div><div className="xs"><Stk db={db} code={l.code} /> · {money(pr.unit)} {pr.brk ? <span className="green">-%{pr.brk} miktar</span> : ""}</div></div><Stepper v={l.qty} step={p.box || 1} onChange={v => S.setCartQty(l.code, v)} /><button className="btn ghost icon sm" onClick={() => S.setCartQty(l.code, 0)} aria-label="Sil"><I n="trash" /></button></div>; })}</div><div className="row between" style={{ padding: 14 }}><span className="mut">Ara toplam (KDV hariç)</span><span className="bb" style={{ fontSize: "1.15em" }}>{money(total)}</span></div></Card> : <Empty icon="cart" t="Sepetiniz boş" s="Ürün arayın, favorilerinizden seçin ya da Ürünler sekmesinden ekleyin." action={<Btn v="soft" onClick={() => S.go("katalog")}>Ürünlere git</Btn>} />}
