function CustAccount({ S }) {
  const { db, cust, custUser: cu, params, big, setBig } = S; const [tab, setTab] = useState(params.tab || (cu.perms.finance ? "cari" : "temsilci")); const [nu, setNu] = useState({ name: "", title: "", email: "" }); const [obj, setObj] = useState(""); const [plQ, setPlQ] = useState("");
  useEffect(() => { if (params.tab) setTab(params.tab); }, [params]);
  const invs = invoicesOf(db, cust.id).sort((a, b) => b.date.localeCompare(a.date)); const open = invs.filter(i => i.total - i.paid > 0.5); const pays = db.payments.filter(p => p.customerId === cust.id).sort((a, b) => b.date.localeCompare(a.date)); const rec = db.recon.filter(r => r.customerId === cust.id); const users = db.custUsers.filter(u => u.customerId === cust.id);
  const setPerm = (uid, k, v) => S.mut(d => { d.custUsers = d.custUsers.map(u => u.id === uid ? { ...u, perms: { ...u.perms, [k]: v } } : u); });
  const plist = useMemo(() => (db.favorites[cust.id] || []).concat(PRODUCTS.filter(p => p.thread === "BSP" || p.thread === "UNF / JIC").slice(0, 60).map(p => p.code)).filter((c, i, a) => a.indexOf(c) === i).map(c => prod(c)), [db, cust.id]);
  const plShown = plist.filter(p => !plQ || norm(p.code + p.name).includes(norm(plQ))).slice(0, 30);
  const opts = [...(cu.perms.finance ? [["cari", "Cari & ödemeler"], ["fatura", "Faturalar"], ["mutabakat", "Mutabakat", rec.filter(r => r.status === "bekliyor").length]] : []), ["fiyat", "Fiyat listem"], ["temsilci", "Temsilcim"], ...(cu.perms.users ? [["kullanici", "Kullanıcılar & yetkiler"]] : []), ["ayar", "Ayarlar"]];
  return <div className="col gap16">
    <div className="row between wrap"><div><h2>{cust.name}</h2><div className="mut sm">{cu.name} · {cu.title} {cust.group === "bayi" && <Badge c="red">BAYİ</Badge>}</div></div></div>
    {cust.group === "bayi" && <TargetBar S={S} />}
    <Tabs v={tab} onChange={setTab} opts={opts} />
    {tab === "cari" && cu.perms.finance && <>
      <div className="grid g4"><Stat l="Cari bakiye" v={money(openBalance(db, cust.id))} d="Toplam açık hesap" /><Stat l="Vadesi geçen" v={money(overdueBalance(db, cust.id))} c={overdueBalance(db, cust.id) > 0 ? "red" : "green"} /><Stat l="7 gün içinde vadesi gelen" v={money(sum(dueSoon(db, cust.id), i => i.total - i.paid))} c="amber" /><Stat l="Kredi limiti" v={money(cust.creditLimit)} d={`Kullanılabilir ${money(Math.max(0, cust.creditLimit - openBalance(db, cust.id)))}`} /></div>
      <Card title="Vadesi gelen ödemeler" pad={false}><Table dense rows={open.sort((a, b) => a.due.localeCompare(b.due)).slice(0, 8)} cols={[{ h: "Fatura", r: i => <div><div className="b">{i.no}</div><div className="xs mut">{(db.orders.find(o => o.id === i.orderId) || {}).no}</div></div> }, { h: "Vade", r: i => daysFromToday(i.due) < 0 ? <span className="red b">{-daysFromToday(i.due)} gün geçti</span> : daysFromToday(i.due) === 0 ? <span className="amber b">Bugün</span> : `${daysFromToday(i.due)} gün sonra` }, { h: "Kalan", num: true, r: i => <span className="b">{money(i.total - i.paid)}</span> }, { h: "Plan", r: i => i.plan ? `${i.plan.filter(p => p.paid).length}/${i.plan.length} taksit` : "Tek ödeme" }]} empty="Açık fatura yok" /></Card>
      <Card title="Ödeme geçmişi" pad={false}><Table dense rows={pays.slice(0, 8)} cols={[{ h: "Tarih", r: p => fdate(p.date) }, { h: "Tutar", num: true, r: p => money(p.amount) }, { h: "Yöntem", k: "method" }, { h: "Fatura", r: p => (db.invoices.find(i => i.id === p.invoiceId) || {}).no }]} empty="Ödeme kaydı yok" /></Card>
      <div className="note">Ödeme bildirimi / online ödeme modülü ikinci fazda. Dekont için temsilcinize WhatsApp'tan yazabilirsiniz.</div>
    </>}
    {tab === "fatura" && cu.perms.finance && <Card pad={false}><Table rows={invs.slice(0, 30)} cols={[{ h: "Fatura", r: i => <div><div className="b">{i.no}</div><div className="xs mut">{fdate(i.date)}</div></div> }, { h: "Tutar", num: true, r: i => money(i.total) }, { h: "Kalan", num: true, r: i => money(i.total - i.paid) }, { h: "Vade", r: i => <div>{fdate(i.due)}{i.plan && <div className="xs mut">{i.plan.map(p => `${fdateS(p.due)} ${p.paid ? "✓" : ""}`).join(" · ")}</div>}</div> }, { h: "Durum", r: i => i.total - i.paid < 0.5 ? <Badge c="g">Ödendi</Badge> : daysFromToday(i.due) < 0 ? <Badge c="r">Vadesi geçti</Badge> : <Badge c="b">Açık</Badge> }, { h: "", r: () => <Btn v="line xs" icon="doc" onClick={() => S.toast("e-Fatura PDF indirildi (demo)")}>PDF</Btn> }]} /></Card>}
    {tab === "mutabakat" && cu.perms.finance && <div className="col gap16">{rec.map(r => <Card key={r.id} title={`${r.period} cari ekstresi`} right={<Badge c={r.status === "onaylandi" ? "g" : r.status === "itiraz" ? "r" : "a"}>{r.status === "onaylandi" ? "Onaylandı" : r.status === "itiraz" ? "İtiraz edildi" : "Yanıt bekleniyor"}</Badge>}><div className="grid g3"><Stat l="Bakiye" v={money(r.balance)} /><Stat l="Açık fatura" v={open.length} /><Stat l="Gönderim" v={fdateS(r.sentAt)} /></div>{r.status === "bekliyor" && <div className="col mt12"><Btn v="green lg" icon="check" onClick={() => { S.mut(d => { const rr = d.recon.find(x => x.id === r.id); rr.status = "onaylandi"; rr.repliedAt = iso(TODAY); }); S.toast("Mutabakat onayınız iletildi", "ok"); }}>Bakiye doğru, onaylıyorum</Btn><div className="row"><div className="grow"><Inp value={obj} onChange={e => setObj(e.target.value)} placeholder="İtiraz: hangi fatura / ödeme eksik?" /></div><Btn v="line" onClick={() => { if (!obj) return; S.mut(d => { const rr = d.recon.find(x => x.id === r.id); rr.status = "itiraz"; rr.objection = obj; rr.repliedAt = iso(TODAY); }); S.toast("İtirazınız muhasebeye iletildi", "ok"); }}>İtiraz et</Btn></div></div>}{r.objection && <div className="note mt8">İtiraz: {r.objection}</div>}</Card>)}{!rec.length && <Empty t="Henüz ekstre gönderilmedi" />}</div>}
    {tab === "fiyat" && <div className="col gap16"><Card><div className="row between wrap"><div><div className="b">Kişisel fiyat listeniz</div><div className="xs mut">{GROUPS_C[cust.group].l} · %{custDisc(db, cust)} iskonto · {Object.keys(cust.special || {}).length} özel fiyat · her an güncel</div></div><div className="row gap6"><Btn v="line sm" icon="doc" onClick={() => S.toast("PDF fiyat listesi indirildi (demo)")}>PDF</Btn><Btn v="line sm" icon="excel" onClick={() => S.toast("Excel fiyat listesi indirildi (demo)")}>Excel</Btn></div></div><div className="mt8"><Search v={plQ} onChange={setPlQ} ph="Listede ara" /></div></Card><Card pad={false}><Table dense rows={plShown} keyOf={p => p.code} onRow={p => S.openProduct(p.code)} cols={[{ h: "Ürün", r: p => <div><div className="b">{p.code}</div><div className="xs mut">{p.name}</div></div> }, { h: "Liste", num: true, r: p => <s className="mut">{money(listTL(db, p.code))}</s> }, { h: "Size özel", num: true, r: p => <span className="b">{money(priceFor(db, cust, p.code, 1).unit)}</span> }, { h: "Kutu (adet)", num: true, r: p => p.box ? `${money(priceFor(db, cust, p.code, p.box).unit)} (${p.box})` : "—" }, { h: "Durum", r: p => <Stk db={db} code={p.code} showEta={false} /> }]} /></Card></div>}
    {tab === "temsilci" && <div className="col gap16"><RepCard S={S} /><Card title="İletişim"><KV items={[["Telefon", userOf(db, cust.rep).phone], ["E-posta", userOf(db, cust.rep).email], ["Bölge", userOf(db, cust.rep).region], ["Merkez", "0312 395 25 78 · bilgi@ozteknikrekor.com.tr"], ["Adres", "Ostim OSB, Ankara"]]} /></Card><Card title="Firma bilgileriniz"><KV items={[["Firma", cust.name], ["Vergi no", cust.vkn], ["Adres", cust.address], ["Vade", `${cust.dueDays} gün`], ["Müşteri grubu", GROUPS_C[cust.group].l], ["Müşteri olma tarihi", fdate(cust.since)]]} /></Card></div>}
    {tab === "kullanici" && cu.perms.users && <div className="col gap16"><div className="note">Departmanlara göre kimin neyi göreceğine siz karar verirsiniz: finans verilerini yalnızca "Finans" yetkisi olanlar görür; "Onay" yetkisi olmayan kullanıcının siparişi önce size gelir.</div>{users.map(u => <Card key={u.id} title={u.name} right={<span className="xs mut">{u.title} · {u.email}</span>}><div className="grid g2 m1">{[["order", "Sipariş verebilir"], ["approve", "Siparişleri onaylar (yönetici)"], ["finance", "Finansal verileri görür"], ["users", "Kullanıcı yönetir"]].map(([k, l]) => <Toggle key={k} label={l} on={!!u.perms[k]} onChange={v => setPerm(u.id, k, v)} />)}</div></Card>)}<Card title="Yeni kullanıcı"><div className="grid g3 m1"><Inp value={nu.name} onChange={e => setNu({ ...nu, name: e.target.value })} placeholder="Ad soyad" /><Inp value={nu.title} onChange={e => setNu({ ...nu, title: e.target.value })} placeholder="Departman / unvan" /><Inp value={nu.email} onChange={e => setNu({ ...nu, email: e.target.value })} placeholder="E-posta" /></div><Btn v="navy mt12" icon="plus" onClick={() => { if (!nu.name || !nu.email) return; S.mut(d => { d.custUsers = [...d.custUsers, { id: nid("cu"), customerId: cust.id, name: nu.name, title: nu.title || "Kullanıcı", email: nu.email, phone: "", perms: { order: true, finance: false, users: false, approve: false } }]; }); setNu({ name: "", title: "", email: "" }); S.toast("Kullanıcı eklendi; giriş bağlantısı e-posta ile gönderildi (demo)", "ok"); }}>Kullanıcı ekle</Btn></Card></div>}
    {tab === "ayar" && <div className="col gap16"><Card title="Görünüm"><Toggle label="Basit mod (büyük yazı, dört büyük düğme)" on={big} onChange={setBig} /><Toggle label="Bildirimler (teklif hazır, kargoda, vade)" on={true} onChange={() => S.toast("Bildirim ayarı kaydedildi (demo)")} /></Card><Card title="Uygulama gibi kullanın"><div className="sm">Ana ekrana ekleyin, uygulama simgesiyle tam ekran açılsın; katalog çevrimdışı da çalışır.</div><KV items={[["iPhone", "Safari → Paylaş → Ana Ekrana Ekle"], ["Android", "Chrome → ⋮ → Ana ekrana ekle"]]} /></Card><Card title="Favoriler"><div className="sm mut">{(db.favorites[cust.id] || []).length} favori ürün · ürün kartından kalp ile ekleyin.</div><div className="pills mt8">{(db.favorites[cust.id] || []).map(c => <button key={c} className="pill" onClick={() => S.openProduct(c)}>{c}</button>)}</div></Card></div>}
  </div>;
}
function CustNotifs({ S }) {
  const { db, cust } = S; const ns = db.notifs.filter(n => n.customerId === cust.id).sort((a, b) => b.t.localeCompare(a.t));
  useEffect(() => { const t = setTimeout(() => S.mut(d => { d.notifs = d.notifs.map(n => n.customerId === cust.id ? { ...n, read: true } : n); }), 1200); return () => clearTimeout(t); }, []);
  return <div className="col gap16"><h2>Bildirimler</h2><Card pad={false}><div className="lst" style={{ padding: "0 8px" }}>{ns.map(n => <Row key={n.id} icon={{ teslim: "check", kampanya: "gift", mutabakat: "doc", kargo: "truck", teklif: "target", fatura: "doc", vade: "wallet", iade: "ret", uyelik: "user", fiyat: "tag", uretim: "factory" }[n.type] || "bell"} ic={n.read ? "" : "r"} t={n.text} s={fdate(n.t)} onClick={() => { if (n.type === "teklif" || n.type === "kargo" || n.type === "teslim" || n.type === "uretim") S.go("siparislerim"); else if (n.type === "mutabakat" || n.type === "fatura" || n.type === "vade") S.go("hesabim", { tab: n.type === "mutabakat" ? "mutabakat" : "cari" }); else if (n.type === "kampanya") S.go("katalog"); else if (n.type === "fiyat") S.go("hesabim", { tab: "fiyat" }); }} />)}{!ns.length && <Empty icon="bell" t="Bildirim yok" />}</div></Card><div className="xs mut">Ana ekrana eklediğinizde bu bildirimler telefonunuza anlık bildirim olarak gelir.</div></div>;
}
