function Shop({ S }) {
  const { db, cart } = S; const [view, setView] = useState("home"); const [q, setQ] = useState(""); const [cat, setCat] = useState(""); const [open, setOpen] = useState(null); const [reg, setReg] = useState(false); const [login, setLogin] = useState(false); const [done, setDone] = useState(null); const [page, setPage] = useState(0);
  const su = S.shopUser; const cust = su ? custOf(db, su.customerId) : null; const active = cust && cust.status === "aktif" ? cust : null;
  const [f, setF] = useState({ name: "", vkn: "", city: "", person: "", email: "", phone: "", pw: "" }); const [le, setLe] = useState("");
  const add = (code, qty) => { S.addToCart(code, qty); S.toast(`${code} sepete eklendi`, "ok"); };
  const list = useMemo(() => PRODUCTS.filter(p => (!cat || p.cat === cat) && (!q || norm(p.code + " " + p.name + " " + specText(p) + " " + p.thread).includes(norm(q)))), [q, cat]);
  const PAGE = 24; const shown = list.slice(0, (page + 1) * PAGE); const gs = by(shown, p => p.gi);
  const total = sum(cart, l => priceFor(db, active, l.code, l.qty).unit * l.qty);
  const register = () => { if (!f.name || !f.email || !f.person) { S.toast("Firma adı, yetkili ve e-posta gerekli", "err"); return; } let uid; S.mut(d => { const id = nid("c"); uid = nid("cu"); d.customers = [...d.customers, { id, name: f.name, short: f.name.split(" ").slice(0, 2).join(" "), group: "son", disc: null, rep: "u3", city: f.city, district: "", vkn: f.vkn, creditLimit: 0, dueDays: 0, currency: "TL", since: iso(TODAY), status: "onay-bekliyor", phone: f.phone, email: f.email, address: f.city, special: {}, tags: ["Vitrin başvurusu"] }]; d.custUsers = [...d.custUsers, { id: uid, customerId: id, name: f.person, title: "Yetkili", email: f.email, phone: f.phone, perms: { order: true, finance: true, users: true, approve: true } }]; addLog(d, null, "Vitrinden üyelik başvurusu", `${f.name} · ${f.city}`); }); setReg(false); S.setShopUser(uid); S.toast("Üyelik başvurunuz alındı — onaylanınca size özel fiyatlar açılır", "ok"); };
  const doLogin = () => { const u = db.custUsers.find(x => x.email.toLowerCase() === le.trim().toLowerCase()); if (!u) { S.toast("Bu e-posta ile üye bulunamadı", "err"); return; } S.setShopUser(u.id); setLogin(false); S.toast(`Hoş geldiniz, ${u.name}`, "ok"); };
  const checkout = () => { if (!su) { setReg(true); return; } S.mut(d => { const no = "SP-2026-" + (++d.seq.order); const o = { id: nid("o"), no, customerId: cust.id, date: iso(TODAY), cur: "TL", lines: cart.map(l => ({ code: l.code, qty: l.qty })), status: active ? "teklif_bekliyor" : "uyelik", src: "vitrin", by: su.id, hist: [{ t: iso(TODAY), s: active ? "Sipariş alındı (vitrin)" : "Sipariş alındı — üyelik onayı bekleniyor", by: su.name + " · vitrin" }] }; if (active) { const qq = buildQuote(d, o); o.quote = { ...qq, no: "TK-2026-" + d.seq.order, status: "taslak" }; } d.orders = [o, ...d.orders]; setDone(o); }); S.clearCart(); setView("done"); };
  const catImg = c => (GROUPS.find(g => g.cat === c.id && g.img) || {}).img;
  return <div className="oz" style={{ minHeight: "100vh", background: "#fff" }}>
    <div className="chead" style={{ background: "#fff", color: "var(--ink)", borderBottom: "1px solid var(--line)" }}><img src={LOGO} alt="" onClick={() => setView("home")} style={{ cursor: "pointer" }} /><div className="grow"><div className="co" style={{ color: "var(--navy)" }}>Özteknik Rekor</div><div className="who mut">{active ? `${cust.short} · size özel fiyatlar` : cust ? `${cust.short} · onay bekleniyor` : "Vitrin · liste fiyatları"}</div></div>
      {!su ? <><Btn v="line sm" onClick={() => setLogin(true)}>Giriş</Btn><Btn v="sm" onClick={() => setReg(true)}>Üye ol</Btn></> : <Btn v="line sm" onClick={() => { S.setShopUser(null); S.toast("Çıkış yapıldı"); }}>{su.name.split(" ")[0]} · Çıkış</Btn>}
      <button className="btn navy sm icon" onClick={() => setView("cart")} aria-label="Sepet" style={{ position: "relative" }}><I n="cart" />{cart.length ? <span className="bdg red" style={{ position: "absolute", top: -6, right: -6, padding: "1px 6px", fontSize: ".65em" }}>{cart.length}</span> : null}</button></div>
    <div className="ccontent">
      {view === "home" && <div className="col gap20">
        <div className="card navy pad2" style={{ background: "linear-gradient(120deg,#0A1F44,#1A4180)", borderRadius: 20 }}><div className="row wrap between gap16"><div style={{ maxWidth: 560 }}><div className="xs" style={{ opacity: .75, letterSpacing: ".06em", fontWeight: 700 }}>ŞUBAT 2026 KATALOĞU · {num(PRODUCTS.length)} ÜRÜN</div><h1 className="mt8" style={{ fontSize: "1.9em" }}>Hidrolik rakor, nipel ve hortum — stoktan, kendi üretimimizden.</h1><p className="mt12" style={{ opacity: .85 }}>Liste fiyatlarını üye olmadan görün. Üye olun, onaylanınca firmanıza özel iskontolu fiyatlar ve sipariş takibi açılsın.</p><div className="row wrap mt16"><Btn onClick={() => setView("list")} icon="grid">Ürünleri incele</Btn>{!su && <Btn v="line" style={{ background: "transparent", color: "#fff", borderColor: "rgba(255,255,255,.4)" }} onClick={() => setReg(true)}>Üye ol</Btn>}</div></div><div className="row wrap gap6" style={{ alignSelf: "flex-end" }}>{["Ostim / Ankara", "1990'dan beri", "EN 10204 3.1 sertifika", "Aynı gün teklif"].map(t => <Badge key={t} c="n" >{t}</Badge>)}</div></div></div>
        <Search v={q} onChange={v => { setQ(v); setView("list"); setPage(0); }} ph="Ürün kodu, diş tipi veya ölçü arayın…" />
        {cust && !active && <Warn c="b" icon="clock">Üyelik başvurunuz onay bekliyor. Onaylanınca bu ekranda size özel fiyatları göreceksiniz; verdiğiniz siparişler de o zaman teklife dönüşür.</Warn>}
        <div><h2>Kategoriler</h2><div className="grid gauto mt12">{CATS.slice(0, 24).map(c => <button key={c.id} className="pc hit" style={{ textAlign: "left" }} onClick={() => { setCat(c.id); setView("list"); setPage(0); }}><div className="img" style={{ aspectRatio: "16/9" }}>{catImg(c) ? <img src={catImg(c)} alt="" loading="lazy" /> : <I n="box" s={32} c="var(--faint)" />}</div><div className="in"><div className="code" style={{ fontSize: ".95em" }}>{c.name}</div><div className="xs mut">{num(PRODUCTS.filter(p => p.cat === c.id).length)} ürün · katalog s. {c.pages[0]}</div></div></button>)}</div><Btn v="line block mt12" onClick={() => { setCat(""); setView("list"); }}>Tüm kategoriler ({CATS.length})</Btn></div>
        <div><h2>Çok satanlar</h2><div className="grid gauto mt12">{["ÖT/110-01", "ÖT/112-01", "ÖT/110-02", "ÖT/107-12", "ÖT/163-22", "ÖT/112-08"].filter(c => prod(c)).map(c => <ProductCard key={c} S={S} p={prod(c)} cust={active} onOpen={setOpen} onAdd={add} />)}</div></div>
        <div className="grid g3 m1"><div className="card soft pad"><div className="b">Fiyat için üye olun</div><div className="sm mut mt4">Onaylanan üyeler grup iskontosu, kampanya ve miktar kırılımlarıyla görür.</div></div><div className="card soft pad"><div className="b">Kendi üretimimiz</div><div className="sm mut mt4">Rakor ve nipeller Ostim'de üretilir; basınç testli, lot izlenebilir.</div></div><div className="card soft pad"><div className="b">Aynı gün teklif</div><div className="sm mut mt4">Sipariş verin, teklif dakikalar içinde hazırlanır; onaylayın, sevkiyat başlasın.</div></div></div>
      </div>}
      {view === "list" && <div className="col gap16"><div className="row wrap"><Btn v="ghost sm" icon="back" onClick={() => setView("home")}>Ana sayfa</Btn><div className="grow"><Search v={q} onChange={v => { setQ(v); setPage(0); }} ph="Kod, ad, ölçü…" /></div></div><div className="pills" style={{ overflow: "auto", flexWrap: "nowrap", paddingBottom: 4 }}><button className={`pill ${!cat ? "on" : ""}`} onClick={() => setCat("")}>Tümü</button>{CATS.map(c => <button key={c.id} className={`pill ${cat === c.id ? "on" : ""}`} onClick={() => { setCat(c.id); setPage(0); }}>{c.name}</button>)}</div>{Object.entries(gs).map(([gi, ps]) => <div key={gi} className="col"><div className="bar"><span>{GROUPS[gi].name}</span><span className="ct">{GROUPS[gi].en}</span></div><div className="grid gauto">{ps.map(p => <ProductCard key={p.code} S={S} p={p} cust={active} onOpen={setOpen} onAdd={add} />)}</div></div>)}{!list.length && <Empty icon="search" t="Ürün bulunamadı" />}{shown.length < list.length && <Btn v="line block" onClick={() => setPage(page + 1)}>Daha fazla ({num(list.length - shown.length)})</Btn>}</div>}
      {view === "cart" && <div className="col gap16"><div className="row"><Btn v="ghost sm" icon="back" onClick={() => setView("list")}>Alışverişe devam</Btn><h2 className="grow">Sepet</h2></div>{cart.length ? <><Card pad={false}><div style={{ padding: "0 12px" }}>{cart.map(l => { const p = prod(l.code); const pr = priceFor(db, active, l.code, l.qty); return <div key={l.code} className="row" style={{ padding: "10px 0", borderBottom: "1px solid var(--line)" }}><div style={{ width: 48, height: 40, borderRadius: 8, background: "#F7F8FA", display: "grid", placeItems: "center", overflow: "hidden", flex: "none" }}><PImg p={p} h={40} /></div><div className="grow" style={{ minWidth: 0 }}><div className="b">{l.code}</div><div className="xs mut ell">{p.name}</div><div className="xs">{money(pr.unit)} · <Stk db={db} code={l.code} showEta={false} /></div></div><Stepper v={l.qty} step={p.box || 1} onChange={v => S.setCartQty(l.code, v)} /><button className="btn ghost icon sm" onClick={() => S.setCartQty(l.code, 0)}><I n="trash" /></button></div>; })}</div><div className="row between" style={{ padding: 14 }}><span className="mut">{active ? "Size özel toplam" : "Liste fiyatı toplamı"} (KDV hariç)</span><span className="bb" style={{ fontSize: "1.15em" }}>{money(total)}</span></div></Card>{!su && <Warn c="b" icon="user">Sipariş vermek için üye olun. Üyeliğiniz onaylanana kadar siparişiniz bekler; onaylanınca iskontolu teklifiniz hazırlanır.</Warn>}{cust && !active && <Warn>Üyeliğiniz onay bekliyor. Sipariş verebilirsiniz; teklif, onaydan sonra hazırlanır.</Warn>}<Btn className="block lg" icon="send" onClick={checkout}>{!su ? "Üye ol ve siparişi gönder" : active ? "Siparişi gönder — teklif iste" : "Siparişi gönder (onay sonrası teklif)"}</Btn></> : <Empty icon="cart" t="Sepet boş" action={<Btn v="soft" onClick={() => setView("list")}>Ürünlere git</Btn>} />}</div>}
      {view === "done" && done && <Card className="ok"><div className="tc" style={{ padding: 12 }}><div className="empty" style={{ padding: 0 }}><div className="ic" style={{ background: "var(--green)", color: "#fff" }}><I n="check" s={30} sw={3} /></div></div><h2 className="mt12">Siparişiniz alındı</h2><div className="mut mt8">{done.no} · {done.lines.length} kalem</div><div className="sm mt12">{done.status === "uyelik" ? "Üyeliğiniz Özteknik tarafından onaylanınca iskontonuz tanımlanır ve teklifiniz hazırlanır. Onay sonrası müşteri portalından takip edebilirsiniz." : "Teklifiniz hazırlanıyor; hazır olunca müşteri portalında onayınıza sunulur."}</div><div className="row mt16" style={{ justifyContent: "center" }}><Btn v="navy" onClick={() => setView("home")}>Vitrine dön</Btn><Btn v="line" onClick={S.logout}>Müşteri portalına git</Btn></div></div></Card>}
    </div>
    <div className="tc xs mut" style={{ padding: 24 }}>Özteknik Rekor Hidrolik · Ostim OSB, Ankara · 0312 395 25 78 · <button className="bluec" onClick={S.logout}>Personel / portal girişi</button></div>
    {open && <ProductSheet S={S} code={open} cust={active} onClose={() => setOpen(null)} onAdd={(code, qty) => add(code, qty)} />}
    {reg && <Sheet title="Üye ol" sub="Firma bilgileriniz Özteknik onayına gider; onaylanınca size özel fiyatlar açılır" onClose={() => setReg(false)} w={560} foot={<Btn className="grow" onClick={register}>Başvuruyu gönder</Btn>}><div className="col"><Field label="Firma adı"><Inp value={f.name} onChange={e => setF({ ...f, name: e.target.value })} placeholder="Trakya Makine Bakım Ltd." /></Field><div className="grid g2 m1"><Field label="Vergi no"><Inp value={f.vkn} onChange={e => setF({ ...f, vkn: e.target.value })} /></Field><Field label="Şehir"><Inp value={f.city} onChange={e => setF({ ...f, city: e.target.value })} /></Field></div><Field label="Yetkili ad soyad"><Inp value={f.person} onChange={e => setF({ ...f, person: e.target.value })} /></Field><div className="grid g2 m1"><Field label="E-posta (giriş için)"><Inp value={f.email} onChange={e => setF({ ...f, email: e.target.value })} inputMode="email" /></Field><Field label="Telefon"><Inp value={f.phone} onChange={e => setF({ ...f, phone: e.target.value })} inputMode="tel" /></Field></div><Field label="Şifre"><Inp type="password" value={f.pw} onChange={e => setF({ ...f, pw: e.target.value })} /></Field><div className="note">Onaydan sonra aynı e-posta ile müşteri portalına da girebilirsiniz.</div></div></Sheet>}
    {login && <Sheet title="Üye girişi" onClose={() => setLogin(false)} w={420} foot={<Btn className="grow" onClick={doLogin}>Giriş yap</Btn>}><div className="col"><Field label="E-posta"><Inp value={le} onChange={e => setLe(e.target.value)} placeholder="elif@trakyamakine.com" inputMode="email" onKeyDown={e => e.key === "Enter" && doLogin()} /></Field><Field label="Şifre"><Inp type="password" placeholder="••••••••" /></Field><div className="xs mut">Demo: elif@trakyamakine.com (onay bekleyen üye) · selim@ankaraismak.com (onaylı bayi)</div></div></Sheet>}
  </div>;
}
/* ------------------------------------------------------------------ */
/*  10 root app                                                        */
/* ------------------------------------------------------------------ */
const STAFF_SCREENS = { bugun: Today, onay: Approvals, gorevler: Tasks, siparisler: Orders, teklifler: Quotes, musteriler: Customers, kampanyalar: Campaigns, iadeler: Returns, depo: Depo, satinalma: Satinalma, uretim: Uretim, sevkiyat: Sevkiyat, finans: Finans, fiyat: Fiyat, raporlar: Raporlar, ozet: Ozet, gecmis: Gecmis, ayarlar: Ayarlar };
const ARRAY_KEYS = ["users", "customers", "custUsers", "orders", "invoices", "payments", "shipments", "returns", "tasks", "campaigns", "priceLists", "suppliers", "pos", "wos", "lots", "log", "notifs", "recon", "templates", "visits", "rawStock", "needs", "logoQueue"];
export default function App() {
  const [db, setDb] = useState(() => makeSeed());
  const [mode, setMode] = useState("login"); const [user, setUser] = useState(null); const [custUser, setCustUser] = useState(null); const [shopUserId, setShopUserId] = useState(null);
  const [mod, setMod] = useState("bugun"); const [params, setParams] = useState({}); const [toasts, setToasts] = useState([]); const [cart, setCart] = useState([]);
  useEffect(() => { if (typeof document !== "undefined") document.title = "Özteknik Rekor · İş Takip"; }, []);
  const toast = useCallback((text, type = "") => { const id = nid("t"); setToasts(t => [...t, { id, text, type }]); setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3200); }, []);
  const mut = useCallback(fn => { setDb(prev => { const d = { ...prev }; ARRAY_KEYS.forEach(k => { if (Array.isArray(d[k])) d[k] = d[k].slice(); }); d.stock = { ...d.stock }; d.eta = { ...d.eta }; d.prices = { ...d.prices }; d.equivalents = { ...d.equivalents }; d.favorites = { ...d.favorites }; d.scores = { ...d.scores }; d.seq = { ...d.seq }; fn(d); return d; }); }, []);
  const nav = useCallback((m, p = {}) => { setMod(m); setParams({ ...p, _t: Date.now() }); window.scrollTo(0, 0); }, []);
  const logout = () => { setMode("login"); setUser(null); setCustUser(null); setShopUserId(null); setMod("bugun"); setParams({}); setCart([]); };
  const addToCart = (code, qty) => setCart(c => { const i = c.findIndex(l => l.code === code); if (i >= 0) return c.map((l, j) => j === i ? { ...l, qty: l.qty + qty } : l); return [...c, { code, qty }]; });
  const setCartQty = (code, qty) => setCart(c => qty <= 0 ? c.filter(l => l.code !== code) : c.map(l => l.code === code ? { ...l, qty } : l));
  const clearCart = () => setCart([]);
  const cust = custUser ? db.customers.find(c => c.id === custUser.customerId) : null;
  const liveCustUser = custUser ? db.custUsers.find(u => u.id === custUser.id) || custUser : null;
  const liveUser = user ? db.users.find(u => u.id === user.id) || user : null;
  const S = { db, mut, toast, nav, logout, user: liveUser, custUser: liveCustUser, cust, mod, params, cart, addToCart, setCartQty, clearCart, shopUser: shopUserId ? db.custUsers.find(u => u.id === shopUserId) : null, setShopUser: setShopUserId };
  const title = mode === "staff" ? (MODULES.find(m => m[0] === mod) || [])[1] || "" : "";
  const Screen = STAFF_SCREENS[mod] || Today;
  const canSee = liveUser && (liveUser.role === "owner" || (liveUser.perms[mod] && liveUser.perms[mod] !== "none"));
  return <>
    <style>{CSS}</style>
    {mode === "login" && <Login db={db} onStaff={u => { setUser(u); setMode("staff"); setMod("bugun"); }} onCustomer={u => { setCustUser(u); setMode("cust"); }} onShop={() => setMode("shop")} />}
    {mode === "staff" && liveUser && <div className="oz"><StaffShell S={S} title={title}>{canSee ? <Screen S={S} key={mod} /> : <Empty icon="lock" t="Bu modül için yetkiniz yok" s="Firma sahibi Kullanıcılar & yetkiler ekranından yetki verebilir." />}</StaffShell></div>}
    {mode === "cust" && liveCustUser && cust && <CustPortal S={S} />}
    {mode === "shop" && <Shop S={S} />}
    <div className="toasts">{toasts.map(t => <div key={t.id} className={`toast ${t.type}`}><I n={t.type === "ok" ? "check" : t.type === "err" ? "warn" : "info"} s={18} />{t.text}</div>)}</div>
  </>;
}
